import React, { useState } from "react";

import IncomeCategory from "./components/IncomeCategory";
import Questionnaire from "./components/Questionnaire";
import SpendingPriority from "./components/SpendingPriority";
import BudgetLimits from "./components/BudgetLimits";

function AppRouter() {
  const [step, setStep] = useState(1);

  const [formData, setFormData] = useState({
    incomeCategory: "",
    questionnaire: {},
    spendingPriorities: {},
    budgetLimits: {}
  });

  const next = () => setStep(s => s + 1);

  const updateData = (data) => {
    setFormData(prev => ({ ...prev, ...data }));
  };

  if (step === 1)
    return <IncomeCategory onNext={next} updateData={updateData} />;

  if (step === 2)
    return <Questionnaire onNext={next} updateData={updateData} />;

  if (step === 3)
    return <SpendingPriority onNext={next} updateData={updateData} />;

  if (step === 4)
    return <BudgetLimits formData={formData} />;

  return <div>Loading...</div>;
}

export default AppRouter;
